<script lang="ts">
  import type { StepStatus, StepValue } from '@fex-design/core/steps/types'; import { stepClassName } from '@fex-design/styles/steps'; import { cn } from '@fex/utils'; import { getContext, setContext, type Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { stepContextKey, stepsContextKey, type StepsContextValue } from './context'
  interface Props extends Omit<HTMLAttributes<HTMLLIElement>, 'class' | 'children'> { value: StepValue; disabled?: boolean; status?: StepStatus; data?: unknown; class?: string; children?: Snippet }
  let { value, disabled = false, status, data, class: className, children, ...rest }: Props = $props(); const steps = getContext<StepsContextValue>(stepsContextKey); if (!steps) throw new Error('Step must be used inside Steps.'); const { snapshot } = steps; const record = $derived({ value, disabled, status, data }); $effect.pre(() => steps.controller.registerStep(record)); const info = $derived.by(() => { void $snapshot; return steps.controller.getStepInfo(value) ?? { value, status: status ?? 'wait', disabled } }); const position = $derived.by(() => { void $snapshot; return Math.max(1, steps.controller.getPosition(value) + 1) }); setContext(stepContextKey, { get info() { return info }, get position() { return position } }); function itemRef(node: HTMLElement) { steps.register(record, node); return { destroy: () => steps.register(record, null) } }
</script>
<li {...rest} use:itemRef class={cn(stepClassName, className)} role={steps.navigation() ? 'button' : undefined} tabindex={steps.navigation() && !info.disabled ? ($snapshot.current === value ? 0 : -1) : undefined} aria-current={$snapshot.current === value ? 'step' : undefined} aria-disabled={info.disabled || undefined} data-status={info.status} data-disabled={info.disabled || undefined} data-navigation={steps.navigation() || undefined} onclick={() => steps.controller.select(value, 'pointer')} onkeydown={(event) => steps.keydown(event, record)}>{@render children?.()}</li>
